keyStatusToMessage = function(upvalues)
    return function(argument1)
        if not argument1 then return "invalid key" end
        local packedArguments = tostring(argument1)
        if packedArguments == "KEY_INVALID" then
            return "key not found"
        elseif packedArguments == "KEY_EXPIRED" then
            return "key expired, get a new one!"
        elseif packedArguments == "HWID_BANNED" then
            return "your hwid is banned!! :c"
        elseif packedArguments == "KEY_INVALIDATED" then
            return "key was disabled"
        elseif packedArguments == "ALREADY_USED" then
            return "one-time key already used"
        elseif packedArguments == "HWID_MISMATCH" then
            return "hwid limit reached"
        elseif packedArguments == "SERVICE_NOT_FOUND" then
            return "service does not exist"
        elseif packedArguments == "SERVICE_MISMATCH" then
            return "key is for another service"
        elseif packedArguments == "PREMIUM_REQUIRED" then
            return "a premium key is required"
        elseif packedArguments == "ERROR" then
            return "network error, please try again"
        elseif packedArguments:match("^http") then
            return "server error (" .. (packedArguments .. ")")
        else
            return packedArguments:lower()
        end
    end
end


